package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// 01 TAX-REC, 13 bytes
type TaxRec struct {
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

var WsEofFlag string = "N"               // PIC X len=1 = "N"
var WsTax decimal.Decimal                 // PIC 9(7)V99
var WsNet decimal.Decimal                 // PIC 9(7)V99
var WsTotalTax decimal.Decimal           // PIC 9(9)V99
var WsCount int64 = 0                    // PIC 9(3)
var WsIncEd string                       // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string                       // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string                       // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string                     // PIC ZZ,ZZZ,ZZ9.99 len=13
var TaxRecData TaxRec

var taxFile *os.File
var taxScanner *bufio.Scanner

var D10000 decimal.Decimal
var D40000 decimal.Decimal
var D1000 decimal.Decimal
var D7000 decimal.Decimal
var D010 decimal.Decimal
var D020 decimal.Decimal
var D030 decimal.Decimal

func init() {
	D10000, _ = decimal.NewFromString("10000.00")
	D40000, _ = decimal.NewFromString("40000.00")
	D1000, _ = decimal.NewFromString("1000.00")
	D7000, _ = decimal.NewFromString("7000.00")
	D010, _ = decimal.NewFromString("0.10")
	D020, _ = decimal.NewFromString("0.20")
	D030, _ = decimal.NewFromString("0.30")
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func openTaxFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	taxFile = f
	taxScanner = bufio.NewScanner(f)
}

func closeTaxFile() {
	if taxFile != nil {
		taxFile.Close()
	}
}

func parsePIC(s string, scale int32) decimal.Decimal {
	cleaned := strings.ReplaceAll(s, " ", "")
	cleaned = strings.ReplaceAll(cleaned, "\t", "")
	if cleaned == "" {
		return decimal.Zero
	}
	digitsOnly := ""
	for _, ch := range cleaned {
		if (ch >= '0' && ch <= '9') || ch == '-' || ch == '+' {
			digitsOnly += string(ch)
		}
	}
	if digitsOnly == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(digitsOnly)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(-scale)
	return d
}

func fitPIC(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if val.IsZero() {
		return val
	}
	neg := val.Sign() < 0
	abs := val.Abs()
	s := abs.StringFixed(scale)
	var intPart, fracPart string
	if scale > 0 {
		idx := strings.LastIndex(s, ".")
		if idx >= 0 {
			intPart = s[:idx]
			fracPart = s[idx+1:]
			if len(fracPart) < int(scale) {
				fracPart = fracPart + strings.Repeat("0", int(scale)-len(fracPart))
			} else if len(fracPart) > int(scale) {
				fracPart = fracPart[:scale]
			}
		} else {
			intPart = s
			fracPart = strings.Repeat("0", int(scale))
		}
	} else {
		intPart = s
		fracPart = ""
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	if intPart == "" {
		intPart = "0"
	}
	newStr := intPart
	if scale > 0 {
		newStr = newStr + "." + fracPart
	}
	d, _ := decimal.NewFromString(newStr)
	if neg {
		d = d.Neg()
	}
	return d
}

func storeRounded(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	r := v.Round(scale)
	return fitPIC(r, intDigits, scale)
}

func storeTrunc(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	return fitPIC(t, intDigits, scale)
}

func formatEdited(val decimal.Decimal, picture string) string {
	negative := val.Sign() < 0
	absVal := val.Abs()

	dotIdx := strings.Index(picture, ".")
	var intPicture, decPicture string
	var decCount int
	if dotIdx != -1 {
		intPicture = picture[:dotIdx]
		decPicture = picture[dotIdx+1:]
		decCount = len(decPicture)
	} else {
		intPicture = picture
		decCount = 0
	}
	intDigitCount := 0
	for _, c := range intPicture {
		if c == 'Z' || c == '9' {
			intDigitCount++
		}
	}

	fixed := absVal.StringFixed(int32(decCount))
	var intPartStr, fracPartStr string
	if decCount > 0 {
		parts := strings.SplitN(fixed, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", decCount)
		}
		if len(fracPartStr) < decCount {
			fracPartStr = fracPartStr + strings.Repeat("0", decCount-len(fracPartStr))
		} else if len(fracPartStr) > decCount {
			fracPartStr = fracPartStr[:decCount]
		}
	} else {
		intPartStr = fixed
		fracPartStr = ""
	}

	if len(intPartStr) > intDigitCount {
		intPartStr = intPartStr[len(intPartStr)-intDigitCount:]
	}
	if len(intPartStr) < intDigitCount {
		intPartStr = strings.Repeat("0", intDigitCount-len(intPartStr)) + intPartStr
	}

	digitIdx := 0
	suppressed := true
	var intOutput strings.Builder
	for _, pc := range intPicture {
		if pc == ',' {
			if suppressed {
				intOutput.WriteByte(' ')
			} else {
				intOutput.WriteByte(',')
			}
		} else if pc == 'Z' {
			d := intPartStr[digitIdx]
			digitIdx++
			if suppressed && d == '0' {
				intOutput.WriteByte(' ')
			} else {
				intOutput.WriteByte(d)
				suppressed = false
			}
		} else if pc == '9' {
			d := intPartStr[digitIdx]
			digitIdx++
			intOutput.WriteByte(d)
			suppressed = false
		} else {
			intOutput.WriteByte(byte(pc))
		}
	}

	var result string
	if decCount > 0 {
		result = intOutput.String() + "." + fracPartStr
	} else {
		result = intOutput.String()
	}

	if negative {
		b := []byte(result)
		firstDigitIdx := -1
		for i, ch := range b {
			if ch >= '0' && ch <= '9' {
				firstDigitIdx = i
				break
			}
		}
		if firstDigitIdx > 0 && b[firstDigitIdx-1] == ' ' {
			b[firstDigitIdx-1] = '-'
			result = string(b)
		} else if firstDigitIdx != -1 {
			if len(b) > 0 {
				b[0] = '-'
				result = string(b)
			}
		}
	}

	if len(result) < len(picture) {
		result = strings.Repeat(" ", len(picture)-len(result)) + result
	} else if len(result) > len(picture) {
		result = result[len(result)-len(picture):]
	}
	return result
}

func formatCount(c int64) string {
	c = c % 1000
	if c < 0 {
		c += 1000
	}
	return fmt.Sprintf("%03d", c)
}

// Paragraphs

func ReadPara() {
	if taxScanner.Scan() {
		line := taxScanner.Text()
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trId := line[0:5]
		incomeStr := line[5:13]
		trIncome := parsePIC(incomeStr, 2)
		TaxRecData.TrId = trId
		TaxRecData.TrIncome = trIncome
	} else {
		if err := taxScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if TaxRecData.TrIncome.Cmp(D10000) <= 0 {
		expr := TaxRecData.TrIncome.Mul(D010)
		WsTax = storeRounded(expr, 7, 2)
	} else if TaxRecData.TrIncome.Cmp(D40000) <= 0 {
		diff := TaxRecData.TrIncome.Sub(D10000)
		expr := D1000.Add(diff.Mul(D020))
		WsTax = storeRounded(expr, 7, 2)
	} else {
		diff := TaxRecData.TrIncome.Sub(D40000)
		expr := D7000.Add(diff.Mul(D030))
		WsTax = storeRounded(expr, 7, 2)
	}
	exprNet := TaxRecData.TrIncome.Sub(WsTax)
	WsNet = storeTrunc(exprNet, 7, 2)

	WsTotalTax = WsTotalTax.Add(WsTax)
	WsTotalTax = storeTrunc(WsTotalTax, 9, 2)

	WsCount = (WsCount + 1) % 1000

	WsIncEd = formatEdited(TaxRecData.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s\n", TaxRecData.TrId, WsIncEd, WsTaxEd, WsNetEd)
	ReadPara()
}

func MainPara() {
	openTaxFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	closeTaxFile()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	MainPara()
}
